{
    const unsigned char* in = (const unsigned char*)input_items[0];
    unsigned char* out = (unsigned char*)output_items[0];
    int consumed = 0;
    int offset = 0;
    int padding;
    unsigned char b;

    for (int i = 0; i < noutput_items; i += kbch) {
        if (frame_size != FECFRAME_MEDIUM) {
            if (fec_block == 0 && inband_type_b == TRUE) {
                padding = 104;
            } else {
                padding = 0;
            }
            add_bbheader(&out[offset], count, padding, TRUE);
            offset = offset + 80;

            if (input_mode == INPUTMODE_HIEFF) {
                for (int j = 0; j < (int)((kbch - 80 - padding) / 8); j++) {
                    if (count == 0) {
                        if (*in != 0x47) {
                            this->d_logger->warn("Transport Stream sync error!");
                        }
                        j--;
                        in++;
                    } else {
                        b = *in++;
                        for (int n = 7; n >= 0; n--) {
                            out[offset++] = b & (1 << n) ? 1 : 0;
                        }
                    }
                    count = (count + 1) % 188;
                    consumed++;
