    memset((void*)(&d_stream_format), 0, sizeof(d_stream_format));
    d_stream_format.mSampleRate = d_input_sample_rate;
    d_stream_format.mFormatID = kAudioFormatLinearPCM;
    d_stream_format.mFormatFlags =
