hdlc_framer_pb_impl::unpack(std::vector<unsigned char>& data)
{
    std::vector<unsigned char> output(data.size() * 8, 0);
    for (size_t i = 0; i < data.size(); i++) {
        for (size_t j = 0; j < 8; j++) {
            output[i * 8 + j] = (data[i] >> j) & 1;
        }
    }
    return output;
}

