dvbt_symbol_inner_interleaver_impl::generate_H()
{
    const int Mmax = d_fft_length;
    const int Nmax = d_payload_length;
    const int Nr = int(ceil(log2(d_fft_length)));
    int q = 0;

    for (int i = 0; i < Mmax; i++) {
        d_h[q] = ((i % 2) << (Nr - 1)) + calculate_R(i);
        if (d_h[q] < Nmax) {
            q++;
        }
    }
}

