context:
jack_sink::work(int noutput_items,
                    gr_vector_const_void_star& input_items,
                    gr_vector_void_star& output_items)
{

    const float** in = (const float**)&input_items[0];

    for (int i = 0; i < d_portcount; i++) {

        int k = 0;

        // write_size and work_size are in bytes
        int work_size = noutput_items * sizeof(sample_t);
        unsigned int write_size;

        while (work_size > 0) {
            unsigned int write_space; // bytes

#ifdef NO_PTHREAD
            while ((write_space = jack_ringbuffer_write_space(d_ringbuffer[i])) <
                   d_jack_buffer_size * sizeof(sample_t)) {
                usleep(1000000 * ((d_jack_buffer_size - write_space / sizeof(sample_t)) /
                                  d_sampling_rate));
            }
#else
            // JACK actually requires POSIX

            pthread_mutex_lock(&d_jack_process_lock);
            while ((write_space = jack_ringbuffer_write_space(d_ringbuffer[i])) <
                   d_jack_buffer_size * sizeof(sample_t)) {

                // wait until jack_sink_process() signals more room
                pthread_cond_wait(&d_ringbuffer_ready, &d_jack_process_lock);
            }
            pthread_mutex_unlock(&d_jack_process_lock);
#endif

            write_space -= write_space % (d_jack_buffer_size * sizeof(sample_t));
            write_size = std::min(write_space, (unsigned int)work_size);

            if (jack_ringbuffer_write(
                    d_ringbuffer[i], (const char*)&(in[i][k]), write_size) < write_size) {
                bail("jack_ringbuffer_write failed", 0);
            }
            work_size -= write_size;
            k += write_size / sizeof(sample_t);
        }
    }

    return noutput_items;
}

dvb_bbheader_bb_impl::general_work(int noutput_items,
                                       gr_vector_int& ninput_items,
                                       gr_vector_const_void_star& input_items,
                                       gr_vector_void_star& output_items)
{
    const unsigned char* in = (const unsigned char*)input_items[0];
    unsigned char* out = (unsigned char*)output_items[0];
    int consumed = 0;
    int offset = 0;
    int padding;
    unsigned char b;

    for (int i = 0; i < noutput_items; i += kbch) {
        if (frame_size != FECFRAME_MEDIUM) {
            if (fec_block == 0 && inband_type_b == TRUE) {
                padding = 104;
            } else {
                padding = 0;
            }
            add_bbheader(&out[offset], count, padding, TRUE);
            offset = offset + 80;

            if (input_mode == INPUTMODE_HIEFF) {
                for (int j = 0; j < (int)((kbch - 80 - padding) / 8); j++) {
                    if (count == 0) {
                        if (*in != 0x47) {
                            this->d_logger->warn("Transport Stream sync error!");
                        }
                        j--;
                        in++;
                    } else {
                        b = *in++;
                        for (int n = 7; n >= 0; n--) {
                            out[offset++] = b & (1 << n) ? 1 : 0;
                        }
                    }
                    count = (count + 1) % 188;
                    consumed++;
                }
                if (fec_block == 0 && inband_type_b == TRUE) {
                    add_inband_type_b(&out[offset], ts_rate);
                    offset = offset + 104;
                }
            } else {
                for (int j = 0; j < (int)((kbch - 80 - padding) / 8); j++) {
                    if (count == 0) {
                        if (*in != 0x47) {
                            this->d_logger->warn("Transport Stream sync error!");
                        }
                        in++;
                        b = crc;
                        crc = 0;
                    } else {
                        b = *in++;
                        crc = crc_tab[b ^ crc];
                    }
                    count = (count + 1) % 188;
                    consumed++;
                    for (int n = 7; n >= 0; n--) {
                        out[offset++] = b & (1 << n) ? 1 : 0;
                    }
                }
                if (fec_block == 0 && inband_type_b == TRUE) {
                    add_inband_type_b(&out[offset], ts_rate);
                    offset = offset + 104;
                }
            }
            if (inband_type_b == TRUE) {
                fec_block = (fec_block + 1) % fec_blocks;
            }
        } else {
            padding = 0;
            add_bbheader(&out[offset], count, padding, nibble);
            offset = offset + 80;
            for (int j = 0; j < (int)((kbch - 80) / 4); j++) {
                if (nibble == TRUE) {
                    if (count == 0) {
                        if (*in != 0x47) {
                            this->d_logger->warn("Transport Stream sync error!");
                        }
                        in++;
                        b = crc;
                        crc = 0;
                    } else {
                        b = *in++;
                        crc = crc_tab[b ^ crc];
                    }
                    bsave = b;
                    count = (count + 1) % 188;
                    consumed++;
                    for (int n = 7; n >= 4; n--) {
                        out[offset++] = b & (1 << n) ? 1 : 0;
                    }
                    nibble = FALSE;
                } else {
                    for (int n = 3; n >= 0; n--) {
                        out[offset++] = bsave & (1 << n) ? 1 : 0;
                    }
                    nibble = TRUE;
                }
            }
        }
    }

    // Tell runtime system how many input items we consumed on
    // each input stream.
    consume_each(consumed);

    // Tell runtime system how many output items we produced.
    return noutput_items;
}

