catv_transport_framing_enc_bb_impl::compute_sum(const unsigned char* bytes)
{
    unsigned char i, bit, out, out1, out2, out3;

    unsigned char tapsG = 0xB1; // 10110001
    unsigned char tapsB = 0x45; //  1000101

    unsigned char register1 = 0;
    unsigned char register2 = 0;
    unsigned char register3 = 0;

    unsigned char result = 0x67;

    unsigned char first7[] = { 0, 0, 0, 0, 0, 0, 0, 0 };

    for (i = 0; i < 8; i++) {
        bit = (bytes[0] >> (7 - i)) & 1;
        out = (register1 & 1) ^ bit;
        if (i < 7) {
            first7[i + 1] = out;
        }
        register1 >>= 1;
        if (out == 1) {
            register1 ^= tapsG;
        }
    }

    for (i = 1; i < 187; i++) {
        register1 = crctable[((register1) ^ BitReverseTable[bytes[i]]) & 0xff];
    }

    for (i = 0; i < 8; i++) {
        out1 = register1 & 1;
        register1 >>= 1;
        if (out1 == 1) {
            register1 ^= tapsG;
        }

        out2 = (register2 & 1) ^ first7[i];
        register2 >>= 1;
        if (first7[i] == 1) {
            register2 ^= tapsB;
        }

        out3 = (register3 & 1) ^ out1 ^ out2;
        register3 >>= 1;
        if ((out1 ^ out2) == 1) {
            register3 ^= tapsG;
        }

        result ^= (out3 << (7 - i));
    }

    return result;
}

