QRfnocF15ColorMapper::loadFromFile(QFile& file)
{
    std::unique_ptr<QLinearGradient> gradient;
    std::string name;
    int kp = -1;

    /* Make sure it's open */
    if (!file.isOpen())
        file.open(QFile::ReadOnly);

    /* Scan until the end */
    std::stringstream ss;
    while (!file.atEnd()) {
        /* Grab a line */
        QByteArray line = file.readLine().simplified();

        /* Skip comments and empty lines */
        if (line.isEmpty() || line.startsWith('#'))
            continue;

        /* Are we in a palette ? */
        if (kp < 0) {
            ss.str(line.toStdString());
            ss >> kp;
            ss >> name;
            ss.clear();

            if (kp) {
                gradient = std::make_unique<QLinearGradient>();
            }
        } else if (kp == 0) {
            /* Create palette */
            QString filename = line;
            QPixmap pixmap(filename);

            addPalette(name, pixmap);

            /* Release name & prepare for next */
            name.clear();

            kp = -1;
        } else {
            std::array<float, 4> f;

            /* Read data point */
            ss.str(line.toStdString());
            for (auto& val : f) {
                ss >> val;
            }
            ss.clear();

            // gradient should already be initialized in this else clause
            gradient->setColorAt(f[0], QColor::fromRgbF(f[1], f[2], f[3]));
            /* Is it over ? */
            if (!--kp) {
                /* Add the newly created palette */
                addPalette(name, *gradient);

                kp = -1;
            }
        }
    }

    return 0;
}

dvbt_pilot_gen::generate_bch_code()
{
    // TODO
    // DO other way: if (feedback == 1) reg = reg ^ polymomial
    // else nothing

    //(n, k) = (127, 113) = (60+67, 60+53)
    unsigned int reg_bch = 0;
    unsigned char data_in[113];

    // fill in 60 zeros
    memset(&data_in[0], 0, 60);
    // fill in TPS data - start bit not included
    memcpy(&data_in[60], &d_tps_data[1], 53);

    // X^14+X^9+X^8+X^6+X^5+X^4+X^2+X+1
    for (int i = 0; i < 113; i++) {
        int feedback = 0x1 & (data_in[i] ^ reg_bch);
        reg_bch = reg_bch >> 1;
        reg_bch |= feedback << 13;
        reg_bch = reg_bch ^ (feedback << 12) ^ (feedback << 11) ^ (feedback << 9) ^
                  (feedback << 8) ^ (feedback << 7) ^ (feedback << 5) ^ (feedback << 4);
    }

    for (int i = 0; i < 14; i++) {
        d_tps_data[i + 54] = 0x1 & (reg_bch >> i);
    }
}

