    int imu = (int)rint(mu * NSTEPS);

    if ((imu < 0) || (imu > NSTEPS)) {
        throw std::runtime_error("mmse_fir_interpolator<sample_t>: imu out of bounds.");
    }

    return filters[imu].filter(input);
}

