d_perm(d_v * d_bsize)
{
    // Init permutation table (used for b[e][do])
    for (int i = 0; i < d_bsize * d_v; i++) {
        if (d_hierarchy == NH) {
            d_perm[i] = ((i % d_v) / (d_v / 2)) + 2 * (i % (d_v / 2));
        } else {
            d_perm[i] = (i % (d_v - 2)) / ((d_v - 2) / 2) + 2 * (i % ((d_v - 2) / 2)) + 2;
        }
    }

    if (d_nsize % d_bsize) {
        this->d_logger->error(
            "Input size must be multiple of block size: nsize: {:d} bsize: {:d}",
            d_nsize,
            d_bsize);
    }
}

