TimeRasterData::incrementResidual()
{
    // After a full set of rows are drawn, we want to add up the
    // residual due to any fractional value of d_cols to appropriately
    // shift the next data in.
    double icols = floor(d_cols);
    d_resid = fmod(d_resid + (d_cols - icols) * d_rows, icols);
}

dvbt_inner_coder_impl::generate_punctured_code(dvb_code_rate_t coderate,
                                                           unsigned char* in,
                                                           unsigned char* out)
{
    int x, y;

    switch (coderate) {
    // X1Y1
    case C1_2:
        generate_codeword(in[0], x, y);
        out[0] = x;
        out[1] = y;
        break;
    // X1Y1Y2
    case C2_3:
        generate_codeword(in[0], x, y);
        out[0] = x;
        out[1] = y;
        generate_codeword(in[1], x, y);
        out[2] = y;
        break;
    // X1Y1Y2X3
    case C3_4:
        generate_codeword(in[0], x, y);
        out[0] = x;
        out[1] = y;
        generate_codeword(in[1], x, y);
        out[2] = y;
        generate_codeword(in[2], x, y);
        out[3] = x;
        break;
    // X1Y1Y2X3Y4X5
    case C5_6:
        generate_codeword(in[0], x, y);
        out[0] = x;
        out[1] = y;
        generate_codeword(in[1], x, y);
        out[2] = y;
        generate_codeword(in[2], x, y);
        out[3] = x;
        generate_codeword(in[3], x, y);
        out[4] = y;
        generate_codeword(in[4], x, y);
        out[5] = x;
        break;
    // X1Y1Y2X3Y4X5Y6X7
    case C7_8:
        generate_codeword(in[0], x, y);
        out[0] = x;
        out[1] = y;
        generate_codeword(in[1], x, y);
        out[2] = y;
        generate_codeword(in[2], x, y);
        out[3] = y;
        generate_codeword(in[3], x, y);
        out[4] = y;
        generate_codeword(in[4], x, y);
        out[5] = x;
        generate_codeword(in[5], x, y);
        out[6] = y;
        generate_codeword(in[6], x, y);
        out[7] = x;
        break;
    default:
        generate_codeword(in[0], x, y);
        out[0] = x;
        out[1] = y;
        break;
    }
}

fll_band_edge_cc_impl::print_taps()
{
    gr::thread::scoped_lock lock(d_setlock);
    std::stringstream ss;
    ss << std::setprecision(4) << std::scientific;
    ss << "Upper Band-edge: [";
    for (const auto& tap : d_taps_upper)
        ss << " " << tap.real() << " + " << tap.imag() << "j,";
