    """
    temp_parsed_data = {}
    if self.parsed_data['io_signature'] or self.parsed_data['message_port']:
        temp_parsed_data['io_signature'] = self.parsed_data['io_signature']
        temp_parsed_data['message_port'] = self.parsed_data['message_port']
