snr_est_m2m4::update(int noutput_items, const gr_complex* input)
{
    for (int i = 0; i < noutput_items; i++) {
        double y1 = abs(input[i]) * abs(input[i]);
        d_y1 = d_alpha * y1 + d_beta * d_y1;

        double y2 = abs(input[i]) * abs(input[i]) * abs(input[i]) * abs(input[i]);
        d_y2 = d_alpha * y2 + d_beta * d_y2;
    }
    return noutput_items;
}

single_pole_iir_filter_cc_impl::work(int noutput_items,
                                         gr_vector_const_void_star& input_items,
                                         gr_vector_void_star& output_items)
{
    const gr_complex* in = (const gr_complex*)input_items[0];
    gr_complex* out = (gr_complex*)output_items[0];
    unsigned int vlen = d_vlen;

    if (d_vlen == 1) {
        for (int i = 0; i < noutput_items; i++) {
            out[i] = d_iir[0].filter(in[i]);
        }
    } else {
        for (int i = 0; i < noutput_items; i++) {
            for (unsigned int j = 0; j < vlen; j++) {
                *out++ = d_iir[j].filter(*in++);
            }
        }
    }

    return noutput_items;
}

