def connect_dialog(self, dialog: QDialog):
        if self.dialog:
            pass  # disconnect?

        self.dialog = dialog
        if isinstance(dialog, ExampleBrowserDialog):
            self.close_button.setHidden(False)
            self.close_button.clicked.connect(dialog.reject)
            self.open_button.clicked.connect(self.done)
            self.tree_widget.itemDoubleClicked.connect(self.done)
        else:
            raise Exception

block_impl::set_iq_balance(size_t channel, const gr_complexd& iq_balance)
{
    validate_channel(channel);

    const bool supported = has_iq_balance(channel);
    /*
     * In case of 0 frequency correction, the method exits to avoid failing
     * in case of the device does not supports DC offset
     */
    if (std::fpclassify(std::norm(iq_balance)) == FP_ZERO) {
        if (supported) {
            d_device->setIQBalance(d_direction, channel, iq_balance);
        }
        return;
    }

    if (!supported) {
        throw std::invalid_argument(this->name() + ": Channel " +
                                    std::to_string(channel) +
                                    " does not support IQ imbalance correction setting");
    }
    d_device->setIQBalance(d_direction, channel, iq_balance);
}

