integrand(double omega, void* params)
{
    double real_ideal;
    double real_approx;
    double real_diff;
    double imag_ideal;
    double imag_approx;
    double imag_diff;

    int i, n;
    int I1;
    double* h;

    /*
     * Ideal differentiator frequency response,
     * with freq modulation to effect a time shift left (advance),
     * and band limited to (-fc, fc).
     * N.B. fc is global_B, mu is global_mu, Fs is 1/Ts, 2*pi*f is omega.
     * fc and Fs are in Hz, and omega is in radians/second.
     *
     * H(f) = j*2*pi*f*Ts * exp(j*2*pi*f*Ts*mu)  for |f| <= fc <= Fs/2
     */
    real_ideal = -omega * Ts * sin(omega * Ts * global_mu);
    imag_ideal = omega * Ts * cos(omega * Ts * global_mu);

    n = global_n;
    h = global_h;
    I1 = -(n / 2);

    real_approx = 0;
    imag_approx = 0;

    for (i = 0; i < n; i++) {
        real_approx += h[i] * cos(-omega * Ts * (i + I1));
        imag_approx += h[i] * sin(-omega * Ts * (i + I1));
    }

    real_diff = real_ideal - real_approx;
    imag_diff = imag_ideal - imag_approx;

    return real_diff * real_diff + imag_diff * imag_diff;
}

def _parse(self, string):
        SI = dict(G=1e9, M=1e6, k=1e3, m=1e-3, u=1e-6, μ=1e-6, n=1e-9)
        scale = 1
        # handle physical units
        if self.unit:
            if string.endswith(self.unit):
                string = string[:-len(self.unit)].strip()
            elif len(self.unit) > 1:
                for prefix, factor in SI.items():
                    if self.unit.startswith(prefix) and string.endswith(self.unit[1:]):
                        string = string[:-len(self.unit[1:])].strip()
                        scale /= factor
        # handle engeneering shortforms like "1k"
        if string[-1] in SI:
            scale *= SI[string[-1]]
            string = string[:-1]
        # handle common typos
        string = string.replace(',', '.').strip()
        # evaluate
        try:
            value = float(string)
        except ValueError:
            # check string before evaluation for security
            string = string.replace(self.unit, '')
            if match := re.search(r'[^0-9.e+\-*/() ]', string):
                raise ValueError("Characters not allowed: " + match.group())
            value = float(numeric_eval(string))

        return scale * value

