unpack_input(unsigned char* code, int bits)
{
    static unsigned int in_buffer = 0;
    static int in_bits = 0;
    unsigned char in_byte;

    if (in_bits < bits) {
        if (fread(&in_byte, sizeof(char), 1, stdin) != 1) {
            *code = 0;
            return (-1);
        }
        in_buffer |= (in_byte << in_bits);
        in_bits += 8;
    }
    *code = in_buffer & ((1 << bits) - 1);
    in_buffer >>= bits;
    in_bits -= bits;
    return (in_bits > 0);
}

