class rpcbufferedget
{
public:
    rpcbufferedget(const unsigned int init_buffer_size = 4096)
        : d_data_needed(false),
          d_data_ready(),
          d_buffer_lock(),
          d_buffer(init_buffer_size)
    {
        ;
    }

    ~rpcbufferedget() { d_data_ready.notify_all(); }

    void offer_data(const TdataType& data)
    {
        if (!d_data_needed)
            return;
        {
            std::scoped_lock lock(d_buffer_lock);
            d_buffer = data;
            d_data_needed = false;
        }
        d_data_ready.notify_one();
    }

    TdataType get()
    {
        std::unique_lock lock(d_buffer_lock);
        d_data_needed = true;
        d_data_ready.wait(lock);
        return d_buffer;
    }

private:
    bool d_data_needed;
    std::condition_variable d_data_ready;
    std::mutex d_buffer_lock;
    TdataType d_buffer;
}

symbol_sync_ff_impl::forecast(int noutput_items,
                                   gr_vector_int& ninput_items_required)
{
    const unsigned ninputs = ninput_items_required.size();

    // The '+ 2' in the expression below is an effort to always have at
    // least one output sample, even if the main loop decides it has to
    // revert one computed sample and wait for the next call to
    // general_work().
    // The d_clock.get_max_avg_period() is also an effort to do the same,
    // in case we have the worst case allowable clock timing deviation on
    // input.
    const int answer = static_cast<int>(ceilf(static_cast<float>(noutput_items + 2) *
                                              d_clock.get_max_avg_period() / d_osps)) +
                       static_cast<int>(d_interp->ntaps());

    for (unsigned i = 0; i < ninputs; i++)
        ninput_items_required[i] = answer;
}

buffer_single_mapped::update_reader_block_history(unsigned history, int delay)
{
    unsigned old_max = d_max_reader_history;
    d_max_reader_history = std::max(d_max_reader_history, history);
    if (d_max_reader_history != old_max) {
        d_write_index = d_max_reader_history - 1;

#ifdef BUFFER_DEBUG
        d_logger->debug("[{}] buffer_single_mapped constructor -- set wr index to: {}",
                        this,
                        d_write_index);
#endif

        // Reset the reader's read index if the buffer's write index has changed.
        // Note that "history - 1" is the nzero_preload value passed to
        // buffer_add_reader.
        for (auto reader : d_readers) {
            reader->d_read_index = d_write_index - (reader->link()->history() - 1);
        }
    }

    // Only attempt to set has history flag if it is not already set
    if (!d_has_history) {
        // Blocks that set delay may set history to delay + 1 but this is
        // not "real" history
        d_has_history = ((static_cast<int>(history) - 1) != delay);
    }
}

