dvb_bbscrambler_bb_impl::init_bb_randomiser(void)
{
    int sr = 0x4A80;
    for (int i = 0; i < FRAME_SIZE_NORMAL; i++) {
        int b = ((sr) ^ (sr >> 1)) & 1;
        bb_randomise[i] = b;
        sr >>= 1;
        if (b) {
            sr |= 0x4000;
        }
    }
    bb_randomize32 = (uint32_t*)&bb_randomise[0];
    bb_randomize64 = (uint64_t*)&bb_randomise[0];
}

