polynomial_vco(float* output, const float* input)
{
    // sin(x) = cos(x + 1.5π) = cos(x - 0.5π)
    for (auto j = iterations / block_size; j; --j) {
        double phase = -GR_M_PI / 2;
        for (uint64_t i = 0; i < block_size; i++) {
            output[i] = polynomial_approx_sin(phase) * amplitude;
            phase += input[i] * k;

            /* we split the handling a bit, because the most common case should be that
             * we're within +-pi; followed by the case where we just positively ran out of
             * that range.
             *
             * The problem with while(too large){make smaller}; while(too small){make
             * larger}; is that at least one float comparison happens without need. The
             * compiler has a hard time noticing that. So, we split into
             *
             * if(too large) { while(too large){make smaller} }
             * else {while(too small) {embiggen}}
             *
             * And because there's then still one initial redundant comparison, we go for
             *
             * if(too large) { do{make smaller} while(still to large); }
             * else {while(too small) {embiggen}}
             *
             */
            if (phase > GR_M_PI) {
                do {
                    phase -= 2 * GR_M_PI;
                } while (phase > GR_M_PI);
            } else {
                while (phase < GR_M_PI) {
                    phase += 2 * GR_M_PI;
                }
            }
        }
    }
}

time_delta_impl::handle_pdu(const pmt::pmt_t& pdu)
{
    // make sure the message is a PDU
    if (!(pmt::is_pdu(pdu))) {
        d_logger->warn("Message received is not a PDU, dropping");
        return;
    }

    gr::thread::scoped_lock l(d_mutex);

    double t_now(
        std::chrono::duration<double>(std::chrono::system_clock::now().time_since_epoch())
            .count());

    pmt::pmt_t meta = pmt::car(pdu);
    pmt::pmt_t sys_time_pmt = pmt::dict_ref(meta, d_time_key, pmt::PMT_NIL);
    if (!pmt::is_real(sys_time_pmt)) {
        d_logger->info("PDU received with no system time at {:f}", t_now);
        return;
    }

    double pdu_time = pmt::to_double(sys_time_pmt);
    double time_delta_ms = (t_now - pdu_time) * 1000.0;
    d_logger->debug("{:s} PDU received at {:f} with time delta {:f} milliseconds",
                    d_name,
                    t_now,
                    time_delta_ms);
    update_stats(time_delta_ms);

    meta = pmt::dict_add(meta, d_delta_key, pmt::from_double(time_delta_ms));
    message_port_pub(msgport_names::pdu(), pmt::cons(meta, pmt::cdr(pdu)));
}

def _get_sock_fd(addr, port, server):
    """
    Get the file descriptor for the socket.
    As a client, block on connect, dup the socket descriptor.
    As a server, block on accept, dup the client descriptor.

    Args:
        addr: the ip address string
        port: the tcp port number
        server: true for server mode, false for client mode

    Returns:
        the file descriptor number
    """
    is_ipv6 = False

    if ":" in addr:
        sock = socket.socket(socket.AF_INET6, socket.SOCK_STREAM, 0)
        is_ipv6 = True
    else:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)

    if server:
        try:
            if is_ipv6:
                bind_addr = addr.replace("::ffff:", "")
                sock.bind((bind_addr, port))
            else:
                sock.bind((addr, port))

            gr.log.info('Waiting for a connection on port ' + str(port))

            sock.listen(1)
            clientsock, address = sock.accept()
            return os.dup(clientsock.fileno())
        except OSError as e:
            gr.log.error('Unable to bind to port ' + str(port))
            gr.log.error('Error: ' + e.strerror)

            if is_ipv6:
                gr.log.error('IPv6 HINT: If trying to start a local listener, '
                             'try "::" for the address.')
            return None
        except:
            gr.log.error('Unable to bind to port ' + str(port))
            return None

    else:
        sock.connect((addr, port))
        return os.dup(sock.fileno())

